/* 功能：创建角色光感面板自有uGUI叶控件、可见滚动条与统一中文提示转发。
 * 边界：只在明确父节点下建立控件，不查找全场、不修改原HUD/环境面板或共享美术。
 * 生命周期：所有节点由调用面板Canvas统一持有；不创建材质实例或设备InputAction。
 */
using System;
using TMPro;
using UnityEngine;
namespace Ossastra.Development.CharacterLighting
{
 internal sealed class CharacterLightingPanelWidgets
 {
  internal static readonly Color Background=new Color(.045f,.07f,.085f,.97f),Ink=new Color(.89f,.94f,.92f,1),Line=new Color(.31f,.52f,.43f,1);
  readonly CharacterLightingPanel owner;readonly TMP_FontAsset font;
  internal CharacterLightingPanelWidgets(CharacterLightingPanel owner,TMP_FontAsset font){this.owner=owner;this.font=font;}
  internal RectTransform Rect(string name,Transform parent){var go=new GameObject(name,typeof(RectTransform));go.transform.SetParent(parent,false);return (RectTransform)go.transform;}
  internal void Stretch(RectTransform r,float left=0,float bottom=0,float right=0,float top=0){r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.pivot=new Vector2(.5f,.5f);r.offsetMin=new Vector2(left,bottom);r.offsetMax=new Vector2(-right,-top);}
  internal UnityEngine.UI.Image Image(RectTransform r,Color color,bool raycast=false){var image=r.gameObject.AddComponent<UnityEngine.UI.Image>();image.color=color;image.raycastTarget=raycast;return image;}
  internal TextMeshProUGUI Text(string name,Transform parent,string value,int size=14){var r=Rect(name,parent);Stretch(r);var text=r.gameObject.AddComponent<TextMeshProUGUI>();text.font=font;text.fontSize=size;text.text=value;text.color=Ink;text.raycastTarget=false;text.richText=false;text.enableWordWrapping=false;text.overflowMode=TextOverflowModes.Ellipsis;text.alignment=TextAlignmentOptions.MidlineLeft;return text;}
  internal void Relay(GameObject go,string hint=""){var relay=go.AddComponent<CharacterLightingPanelInputRelay>();relay.owner=owner;relay.description=hint;}
  internal RectTransform Row(Transform parent,string name,float height=32){var r=Rect(name,parent);var layout=r.gameObject.AddComponent<UnityEngine.UI.LayoutElement>();layout.preferredHeight=layout.minHeight=height;return r;}
  internal void Title(Transform parent,string text){var r=Row(parent,"Section",29);var label=Text("Title",r,text,15);label.fontStyle=FontStyles.Bold;label.color=new Color(.7f,.9f,.78f,1);}
  internal UnityEngine.UI.Button Button(Transform parent,string name,string text,Action clicked,string hint="")
  {var r=Row(parent,name);var image=Image(r,new Color(.12f,.19f,.19f,1),true);var button=r.gameObject.AddComponent<UnityEngine.UI.Button>();button.targetGraphic=image;var border=r.gameObject.AddComponent<UnityEngine.UI.Outline>();border.effectColor=Line;border.effectDistance=new Vector2(1,-1);Text("Label",r,text).alignment=TextAlignmentOptions.Center;button.onClick.AddListener(()=>clicked());Relay(r.gameObject,hint);return button;}
  internal UnityEngine.UI.Toggle Toggle(Transform parent,string name,string text,Action<bool> changed,string hint)
  {var r=Row(parent,name);var toggle=r.gameObject.AddComponent<UnityEngine.UI.Toggle>();toggle.targetGraphic=Image(r,Color.clear,true);var box=Rect("Box",r);box.anchorMin=box.anchorMax=new Vector2(0,.5f);box.pivot=new Vector2(0,.5f);box.anchoredPosition=new Vector2(1,0);box.sizeDelta=new Vector2(21,21);Image(box,new Color(.09f,.14f,.14f,1));var check=Rect("Check",box);Stretch(check,4,4,4,4);toggle.graphic=Image(check,new Color(.5f,.83f,.65f,1));var label=Text("Label",r,text);Stretch(label.rectTransform,30,0,0,0);toggle.onValueChanged.AddListener(v=>changed(v));Relay(r.gameObject,hint);return toggle;}
  internal UnityEngine.UI.Slider Slider(Transform parent,string name,string title,float min,float max,Action<float> changed,string hint,out TextMeshProUGUI label)
  {var row=Row(parent,name+"Row",49);label=Text("Label",row,title);label.rectTransform.anchorMin=new Vector2(0,.5f);label.rectTransform.anchorMax=Vector2.one;label.rectTransform.offsetMin=label.rectTransform.offsetMax=Vector2.zero;var r=Rect(name,row);r.anchorMin=Vector2.zero;r.anchorMax=new Vector2(1,.5f);r.offsetMin=new Vector2(3,4);r.offsetMax=new Vector2(-3,-1);Image(r,new Color(.1f,.17f,.17f,1),true);var slider=r.gameObject.AddComponent<UnityEngine.UI.Slider>();slider.minValue=min;slider.maxValue=max;var fillArea=Rect("FillArea",r);Stretch(fillArea,5,5,5,5);var fill=Rect("Fill",fillArea);Stretch(fill);Image(fill,new Color(.33f,.59f,.46f,1));slider.fillRect=fill;var handleArea=Rect("HandleArea",r);Stretch(handleArea,6,0,6,0);var handle=Rect("Handle",handleArea);handle.anchorMin=Vector2.zero;handle.anchorMax=new Vector2(0,1);handle.sizeDelta=new Vector2(12,0);slider.handleRect=handle;slider.targetGraphic=Image(handle,new Color(.79f,.92f,.83f,1),true);slider.onValueChanged.AddListener(v=>changed(v));Relay(r.gameObject,hint);Relay(row.gameObject,hint);return slider;}
  internal TMP_Dropdown Dropdown(Transform parent,string name,string title,Action<int> changed,string hint)
  {
   var row=Row(parent,name+"Row",61);var text=Text("Title",row,title);text.rectTransform.anchorMin=new Vector2(0,.55f);text.rectTransform.anchorMax=Vector2.one;text.rectTransform.offsetMin=text.rectTransform.offsetMax=Vector2.zero;
   var r=Rect(name,row);r.anchorMin=Vector2.zero;r.anchorMax=new Vector2(1,.55f);r.offsetMin=new Vector2(0,1);r.offsetMax=new Vector2(0,-1);var image=Image(r,new Color(.12f,.19f,.19f,1),true);var drop=r.gameObject.AddComponent<TMP_Dropdown>();drop.targetGraphic=image;var caption=Text("Caption",r,"");Stretch(caption.rectTransform,8,0,20,0);drop.captionText=caption;var arrow=Text("Arrow",r,"▾");arrow.alignment=TextAlignmentOptions.MidlineRight;Stretch(arrow.rectTransform,0,0,7,0);
   var template=Rect("Template",r);template.anchorMin=Vector2.zero;template.anchorMax=new Vector2(1,0);template.pivot=new Vector2(.5f,1);template.sizeDelta=new Vector2(0,136);Image(template,Background,true);var scroll=template.gameObject.AddComponent<UnityEngine.UI.ScrollRect>();scroll.horizontal=false;scroll.movementType=UnityEngine.UI.ScrollRect.MovementType.Clamped;var viewport=Rect("Viewport",template);Stretch(viewport);Image(viewport,Color.white,true);viewport.gameObject.AddComponent<UnityEngine.UI.Mask>().showMaskGraphic=false;var content=Rect("Content",viewport);content.anchorMin=new Vector2(0,1);content.anchorMax=Vector2.one;content.pivot=new Vector2(.5f,1);content.sizeDelta=new Vector2(0,31);var item=Rect("Item",content);item.anchorMin=new Vector2(0,.5f);item.anchorMax=new Vector2(1,.5f);item.sizeDelta=new Vector2(0,31);var toggle=item.gameObject.AddComponent<UnityEngine.UI.Toggle>();toggle.targetGraphic=Image(item,new Color(.15f,.26f,.22f,1),true);var check=Rect("Check",item);check.anchorMin=check.anchorMax=new Vector2(0,.5f);check.pivot=new Vector2(0,.5f);check.anchoredPosition=new Vector2(4,0);check.sizeDelta=new Vector2(15,15);toggle.graphic=Image(check,new Color(.55f,.86f,.67f,1));var itemText=Text("ItemLabel",item,"");Stretch(itemText.rectTransform,27,0,5,0);drop.itemText=itemText;drop.template=template;scroll.viewport=viewport;scroll.content=content;Relay(item.gameObject,hint);template.gameObject.SetActive(false);drop.onValueChanged.AddListener(v=>changed(v));Relay(r.gameObject,hint);return drop;
  }
  internal UnityEngine.UI.ScrollRect ScrollBody(RectTransform body,out RectTransform content)
  {
   var scroll=body.gameObject.AddComponent<UnityEngine.UI.ScrollRect>();scroll.horizontal=false;scroll.vertical=true;scroll.movementType=UnityEngine.UI.ScrollRect.MovementType.Clamped;scroll.scrollSensitivity=30;
   var viewport=Rect("Viewport",body);Stretch(viewport,0,0,19,0);Image(viewport,Color.white,true);viewport.gameObject.AddComponent<UnityEngine.UI.Mask>().showMaskGraphic=false;
   content=Rect("Content",viewport);content.anchorMin=new Vector2(0,1);content.anchorMax=Vector2.one;content.pivot=new Vector2(.5f,1);content.sizeDelta=Vector2.zero;var layout=content.gameObject.AddComponent<UnityEngine.UI.VerticalLayoutGroup>();layout.padding=new RectOffset(4,5,3,5);layout.spacing=4;layout.childControlWidth=layout.childControlHeight=true;layout.childForceExpandWidth=true;layout.childForceExpandHeight=false;var fitter=content.gameObject.AddComponent<UnityEngine.UI.ContentSizeFitter>();fitter.horizontalFit=UnityEngine.UI.ContentSizeFitter.FitMode.Unconstrained;fitter.verticalFit=UnityEngine.UI.ContentSizeFitter.FitMode.PreferredSize;
   var barRect=Rect("VerticalScrollbar",body);barRect.anchorMin=new Vector2(1,0);barRect.anchorMax=Vector2.one;barRect.pivot=new Vector2(1,.5f);barRect.offsetMin=new Vector2(-14,0);barRect.offsetMax=Vector2.zero;Image(barRect,new Color(.1f,.17f,.17f,1),true);var bar=barRect.gameObject.AddComponent<UnityEngine.UI.Scrollbar>();bar.direction=UnityEngine.UI.Scrollbar.Direction.BottomToTop;var area=Rect("SlidingArea",barRect);Stretch(area,2,2,2,2);var handle=Rect("Handle",area);Stretch(handle);bar.handleRect=handle;bar.targetGraphic=Image(handle,new Color(.43f,.68f,.54f,1),true);Relay(barRect.gameObject,"拖动滚动条查看下方参数与保存入口；只捕获本窗口输入。");scroll.viewport=viewport;scroll.content=content;scroll.verticalScrollbar=bar;scroll.verticalScrollbarVisibility=UnityEngine.UI.ScrollRect.ScrollbarVisibility.Permanent;Relay(body.gameObject);return scroll;
  }
 }
}

